import {HBAR,observables} from './engine.js';
export const settings={n:12,assembly:'helix',hand:1,twist:55,radius:1.2,rise:.36,separation:3.5,j:.025,drive:.006,gamma:.003,relax:.0005,carrier:5.64,transition:5.64,pol:'x',ell:0,waist:500,offset:0,center:80,sigma:25,end:500,dt:.5};
const dot=(a,b)=>a.reduce((s,v,i)=>s+v*b[i],0);
export function build(params={}){let p={...settings,...params},g=[];if(p.assembly==='monomer')p.n=1;if(p.assembly==='dimer')p.n=2;let groups=p.assembly==='bundle'?3:p.assembly==='network'?4:1;
for(let i=0;i<p.n;i++){let group=Math.floor(i/(p.n/groups)),local=i%(p.n/groups),a=p.hand*local*p.twist*Math.PI/180,sz=p.n/groups;let r=[p.radius*Math.cos(a),p.radius*Math.sin(a),(local-(sz-1)/2)*p.rise],mu=[-Math.sin(a)*Math.sqrt(.75),Math.cos(a)*Math.sqrt(.75),.5];if(groups>1){let b=group*2*Math.PI/groups;if(p.assembly==='network'){let transform=v=>{let x=.5*v[0]+Math.sqrt(.75)*v[2],z=.5*v[2]-Math.sqrt(.75)*v[0];return [x*Math.cos(b)-v[1]*Math.sin(b),x*Math.sin(b)+v[1]*Math.cos(b),z];};r=transform(r);mu=transform(mu);}r[0]+=p.separation*Math.cos(b);r[1]+=p.separation*Math.sin(b);}if(p.n===1)r=[0,0,0];g.push({r,mu,group});}
let d=p.n+1,H=new Float64Array(d*d);const r0=1.2;for(let i=0;i<p.n;i++){H[(i+1)*d+i+1]=p.transition-p.carrier;for(let j=0;j<i;j++){let dr=g[i].r.map((x,k)=>x-g[j].r[k]),r=Math.hypot(...dr),u=dr.map(x=>x/r),v=p.j*(r0/r)**3*(dot(g[i].mu,g[j].mu)-3*dot(g[i].mu,u)*dot(g[j].mu,u));H[(i+1)*d+j+1]=H[(j+1)*d+i+1]=v;}}return {p,g,d,H};}
export function beam(x,y,z,p){let xx=x-p.offset*p.waist,r=Math.hypot(xx,y),a=Math.atan2(y,xx),l=Math.abs(p.ell);let amp=Math.exp(-((r/p.waist)**2))*(l?Math.pow(Math.sqrt(2)*r/p.waist,l)/Math.sqrt(l===2?2:1):1),phase=p.ell*a+2*Math.PI*z/(1239.841984/p.carrier);return [amp*Math.cos(phase),amp*Math.sin(phase)];}
export function polarization(p){return p.pol==='plus'?[[Math.SQRT1_2,0],[0,Math.SQRT1_2],[0,0]]:p.pol==='minus'?[[Math.SQRT1_2,0],[0,-Math.SQRT1_2],[0,0]]:p.pol==='y'?[[0,0],[1,0],[0,0]]:[[1,0],[0,0],[0,0]];}
export function complexH(m,t){let {p,g,d}=m,re=m.H.slice(),im=new Float64Array(d*d),e=polarization(p),env=Math.exp(-.5*((t-p.center)/p.sigma)**2);g.forEach((s,i)=>{let b=beam(...s.r,p),mr=0,mi=0;for(let k=0;k<3;k++){mr+=s.mu[k]*e[k][0];mi+=s.mu[k]*e[k][1];}let vr=-p.drive*env*(mr*b[0]-mi*b[1]),vi=-p.drive*env*(mr*b[1]+mi*b[0]),a=i+1;re[a*d]=re[a]=vr;im[a*d]=vi;im[a]=-vi;});return [re,im];}
export function rhs(m,t,y){let {d,p}=m,L=d*d,[hr,hi]=complexH(m,t),out=new Float64Array(2*L);for(let a=0;a<d;a++)for(let b=0;b<d;b++){let cr=0,ci=0;for(let k=0;k<d;k++){let ak=a*d+k,kb=k*d+b;cr+=hr[ak]*y[kb]-hi[ak]*y[L+kb]-y[ak]*hr[kb]+y[L+ak]*hi[kb];ci+=hr[ak]*y[L+kb]+hi[ak]*y[kb]-y[ak]*hi[kb]-y[L+ak]*hr[kb];}let q=a*d+b,rate=p.relax*((a>0)+(b>0))/2+(a===b?0:p.gamma*((a>0)+(b>0))/2);out[q]=ci/HBAR-rate*y[q];out[L+q]=-cr/HBAR-rate*y[L+q];}for(let i=1;i<d;i++)out[0]+=p.relax*y[i*d+i];return out;}
export function advance(m,t,y,dt){let add=(k,s)=>y.map((v,i)=>v+s*k[i]),a=rhs(m,t,y),b=rhs(m,t+dt/2,add(a,dt/2)),c=rhs(m,t+dt/2,add(b,dt/2)),e=rhs(m,t+dt,add(c,dt));return y.map((v,i)=>v+dt*(a[i]+2*b[i]+2*c[i]+e[i])/6);}
export function solve(params={}){let m=build(params),{p,d}=m;let norm=Math.max(...Array.from({length:d},(_,i)=>Array.from({length:d},(_,j)=>Math.abs(m.H[i*d+j])).reduce((a,b)=>a+b,0)))+p.drive*Math.sqrt(p.n);let target=Math.min(p.dt,.12*HBAR/Math.max(norm,1e-12));p.dt=2/Math.ceil(2/target);let y=new Float64Array(2*d*d);y[0]=1;let frames=[],stride=Math.round(2/p.dt);for(let s=0;s<=Math.round(p.end/p.dt);s++){let t=s*p.dt;if(s%stride===0)frames.push({...observables(m,y,t),rho:Array.from(y)});if(t<p.end)y=advance(m,t,y,p.dt);}return {m,frames};}
// Real symmetric Jacobi eigensolver, sorted eigenpairs.
export function eigen(A){let n=A.length;A=A.map(r=>r.slice());let V=Array.from({length:n},(_,i)=>Array.from({length:n},(_,j)=>+(i===j)));for(let it=0;it<100*n*n;it++){let a=0,b=0,m=0;for(let i=0;i<n;i++)for(let j=i+1;j<n;j++)if(Math.abs(A[i][j])>m){m=Math.abs(A[i][j]);a=i;b=j;}if(m<1e-13)break;let th=.5*Math.atan2(2*A[a][b],A[b][b]-A[a][a]),c=Math.cos(th),s=Math.sin(th),aa=A[a][a],bb=A[b][b],ab=A[a][b];for(let k=0;k<n;k++)if(k!==a&&k!==b){let ka=A[k][a],kb=A[k][b];A[k][a]=A[a][k]=c*ka-s*kb;A[k][b]=A[b][k]=s*ka+c*kb;}A[a][a]=c*c*aa-2*c*s*ab+s*s*bb;A[b][b]=s*s*aa+2*c*s*ab+c*c*bb;A[a][b]=A[b][a]=0;for(let k=0;k<n;k++){let va=V[k][a],vb=V[k][b];V[k][a]=c*va-s*vb;V[k][b]=s*va+c*vb;}}return Array.from({length:n},(_,i)=>({value:A[i][i],vector:V.map(r=>r[i])})).sort((a,b)=>a.value-b.value);}
export function modes(m){return eigen(Array.from({length:m.p.n},(_,i)=>Array.from({length:m.p.n},(_,j)=>m.H[(i+1)*m.d+j+1])));}
export function geometryScan(p){return Array.from({length:51},(_,i)=>{let twist=25+i*1.5,h=.02,lo=modes(build({...p,twist:twist-h})),hi=modes(build({...p,twist:twist+h})),mid=modes(build({...p,twist})),overlap=dot(lo[0].vector,hi[0].vector)**2,gap=mid.length>1?mid[1].value-mid[0].value:Infinity;return {twist,metric:gap<1e-7?null:Math.max(0,1-overlap)/(2*h*Math.PI/180)**2,gap:gap===Infinity?null:gap};});}
export function graph(m,threshold=.002){let n=m.p.n,edges=[],L=Array.from({length:n},()=>Array(n).fill(0)),parent=Array.from({length:n},(_,i)=>i);function root(i){while(parent[i]!==i)i=parent[i];return i;}for(let i=0;i<n;i++)for(let j=i+1;j<n;j++)if(Math.abs(m.H[(i+1)*m.d+j+1])>=threshold){edges.push([i,j]);L[i][i]++;L[j][j]++;L[i][j]--;L[j][i]--;parent[root(i)]=root(j);}let components=new Set(parent.map((_,i)=>root(i))).size;return {edges,components,cycles:edges.length-n+components,spectrum:eigen(L).map(e=>e.value)};}
// Dimensionless coherent far-field dipole amplitude. No absolute radiometry or incident-field interference.
export function radiation(m,f,direction){let re=[0,0,0],im=[0,0,0],L=m.d*m.d,k=2*Math.PI/(1239.841984/m.p.carrier);m.g.forEach((s,i)=>{let phase=-k*dot(direction,s.r),a=f.rho[(i+1)*m.d],b=f.rho[L+(i+1)*m.d],cr=a*Math.cos(phase)-b*Math.sin(phase),ci=a*Math.sin(phase)+b*Math.cos(phase),proj=dot(direction,s.mu);for(let j=0;j<3;j++){let transverse=s.mu[j]-direction[j]*proj;re[j]+=transverse*cr;im[j]+=transverse*ci;}});return {re,im,intensity:dot(re,re)+dot(im,im)};}
export function compare(a,b){if(a.m.d!==b.m.d)throw Error('State spaces differ');return a.frames.map((f,i)=>({t:f.t,distance:Math.sqrt(f.rho.reduce((s,x,k)=>s+(x-b.frames[i].rho[k])**2,0)),populationDifference:f.excited-b.frames[i].excited}));}
export function rfField(t,kind,B0,B1,freq){let a=2*Math.PI*freq*t;return kind==='rotating'?[B1*Math.cos(a),B1*Math.sin(a),B0]:kind==='linear'?[B1*Math.cos(a),0,B0]:[0,0,B0+B1*(Math.sin(a)>=0?1:-1)];}
